const cards = $('Um item por card').all().map(i => i.json);
const pecaId = $('Montar contexto').first().json.peca_id;
const out = [];
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  if (!itens[i].binary || !itens[i].binary.data) continue;
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const mime = itens[i].binary.data.mimeType || 'image/jpeg';
  const card = cards[i] || { numero: i + 1, prompt: '', rodada: 0 };
  out.push({ json: { peca_id: pecaId, numero: card.numero, rodada: card.rodada, prompt: card.prompt, provedor: 'magnific/flux-pro-v1-1', data_url: 'data:' + mime + ';base64,' + buf.toString('base64') } });
}
// Sem nenhuma imagem, segue mesmo assim: a aprovação da arte abre com os cards no fundo da marca.
return out.length ? out : [{ json: { sem_imagem: true } }];

